const prep = $('Preparar Sesión').first().json;
let carrito = [];
try { carrito = JSON.parse(prep.carrito || '[]'); } catch (e) { carrito = []; }
const menu = $('Leer Menú (confirmar)').all();
const out = [];
for (const c of carrito) {
  const prod = menu.find(i => String(i.json.id_productos) === String(c.id_productos));
  const stockActual = prod ? (parseInt(prod.json.stock, 10) || 0) : 0;
  const nuevo = Math.max(0, stockActual - c.cantidad);
  out.push({ json: { id_productos: String(c.id_productos), stock: nuevo } });
}
return out;

const t = $('Telegram Trigger Cocina').first().json;
const raw = (t.message && t.message.text ? t.message.text : '').toString().trim();
const parts = raw.split(' ').filter(p => p !== '');
const id_pedido = parts.length > 0 ? parts[0] : '';
const estadoRaw = parts.slice(1).join(' ').toLowerCase().trim();
let estado = '';
if (['recibido', '1'].indexOf(estadoRaw) !== -1) estado = 'Recibido';
else if (['en preparacion', 'en preparación', 'preparacion', 'preparación', '2'].indexOf(estadoRaw) !== -1) estado = 'En preparación';
else if (['entregado', '3'].indexOf(estadoRaw) !== -1) estado = 'Entregado';
const valido = id_pedido.indexOf('PED-') === 0 && estado !== '';
return [{ json: { valido: valido, id_pedido: id_pedido, estado: estado, raw: raw } }];

const found = $input.first() ? $input.first().json : {};
const parse = $('Parsear Comando Cocina').first().json;
const tieneUsuario = found && found.id_usuario;
if (!tieneUsuario) {
  return [{ json: { encontrado: false, id_pedido: parse.id_pedido } }];
}
const mensajeCliente = '🔔 Actualización de tu pedido ' + found.id_pedido + '\nNuevo estado: ' + parse.estado;
const mensajeCocina = '✅ Pedido ' + found.id_pedido + ' actualizado a: ' + parse.estado;
return [{ json: { encontrado: true, id_pedido: found.id_pedido, id_usuario: found.id_usuario, estado: parse.estado, mensajeCliente: mensajeCliente, mensajeCocina: mensajeCocina } }];

const rows = $input.all().filter(i => i.json && i.json.id_pedido);
const hoy = new Date().toISOString().slice(0, 10);
const delDia = rows.filter(r => String(r.json.fecha) === hoy);
let total = 0;
const conteo = {};
for (const r of delDia) {
  total += parseFloat(r.json.total_pago) || 0;
  let items = [];
  try { items = JSON.parse(r.json.detalles_pedido || '[]'); } catch (e) { items = []; }
  for (const it of items) {
    const nombre = it.nombre || ('Producto ' + it.id_productos);
    conteo[nombre] = (conteo[nombre] || 0) + (parseInt(it.cantidad, 10) || 0);
  }
}
const ranking = Object.keys(conteo).map(k => ({ nombre: k, cantidad: conteo[k] })).sort((a, b) => b.cantidad - a.cantidad);
let productosHtml = '';
if (ranking.length === 0) productosHtml = '<li>No hubo ventas hoy</li>';
else for (const p of ranking) productosHtml += '<li>' + p.nombre + ': ' + p.cantidad + '</li>';
const html = '<h2>Reporte diario DeliveryBot - ' + hoy + '</h2>' +
  '<p><b>Pedidos:</b> ' + delDia.length + '</p>' +
  '<p><b>Total recibido:</b> $' + total.toFixed(2) + '</p>' +
  '<h3>Productos más vendidos</h3><ul>' + productosHtml + '</ul>';
return [{ json: { fecha: hoy, total: total.toFixed(2), pedidos: delDia.length, html: html } }];
